// C program for the function called haveSameElements
// Contains target function implementation and dependency signatures

#include <assert.h> /// for assertions
#include <stdio.h> /// for IO operations
#include <stdlib.h> /// for memory management

// Target function implementation
int haveSameElements(int *array1, int *array2, int length) {
    if (array1 == NULL || array2 == NULL || length < 0) {
        return 0;
    }
    if (length == 0) {
        return 1;
    }

    // Create a copy of array2 to mark elements as "used"
    int *temp = (int*) malloc(sizeof(int) * length);
    if (temp == NULL) {
        return 0;
    }
    int *used = (int*) calloc(length, sizeof(int));
    if (used == NULL) {
        free(temp);
        return 0;
    }

    for (int i = 0; i < length; ++i) {
        temp[i] = array2[i];
    }

    for (int i = 0; i < length; ++i) {
        int found = 0;
        for (int j = 0; j < length; ++j) {
            if (!used[j] && array1[i] == temp[j]) {
                used[j] = 1;
                found = 1;
                break;
            }
        }
        if (!found) {
            free(temp);
            free(used);
            return 0;
        }
    }

    free(temp);
    free(used);
    return 1;
}

